function predictionArtwork(){return `<svg class="ai-rate-art" width="120" height="120" viewBox="0 0 120 120" fill="none" aria-hidden="true"><defs><linearGradient id="ai-orbit" x1="10" y1="40" x2="110" y2="80" gradientUnits="userSpaceOnUse"><stop stop-color="#003cff"/><stop offset=".5" stop-color="#3699ee"/><stop offset="1" stop-color="#76f5e9"/></linearGradient></defs><ellipse cx="60" cy="60" rx="52" ry="26" stroke="url(#ai-orbit)" stroke-width="4"/><ellipse cx="60" cy="60" rx="52" ry="26" transform="rotate(90 60 60)" stroke="url(#ai-orbit)" stroke-width="4"/></svg><span class="ai-rate-art-star" aria-hidden="true"></span>`;}
function scatterChart(){
 // Only visible sample points from the supplied reference; red marks omitted.
 const points=[[18,166],[22,180],[29,166],[31,181],[39,45],[47,130],[48,198],[52,164],[78,59],[95,52],[105,109],[112,187],[113,54],[125,102],[132,53],[137,49],[149,172],[151,186],[165,73],[168,104],[176,174],[184,151],[185,196],[190,120],[200,103],[210,101],[218,121],[219,150],[220,166],[221,183],[225,201],[230,155],[231,114],[232,99],[234,55],[237,58],[239,72],[240,91],[241,103],[241,131],[242,155],[242,164],[244,180],[245,197],[239,202]];
 return `<svg class="ai-rate-chart" viewBox="0 0 320 280" role="img" aria-label="나와 비슷한 사람들이 받은 대출 분포 예시"><text x="0" y="15" class="chart-muted">한도(만원)</text>${[[32,'1,200'],[92,'1,030'],[152,'870'],[212,'700']].map(([y,label])=>`<text x="0" y="${y+4}">${label}</text><line x1="64" y1="${y}" x2="312" y2="${y}" stroke="#e4e6ed" stroke-dasharray="2 2"/>`).join('')}${points.map(([x,y])=>`<circle cx="${x+64}" cy="${y}" r="3.2" fill="#da5fe9" opacity=".85"/>`).join('')}<line x1="64" y1="228" x2="312" y2="228" stroke="#949bb0"/>${[[64,'10.7'],[147,'10.9'],[229,'11.1'],[312,'11.3']].map(([x,label])=>`<text x="${x}" y="248" text-anchor="middle">${label}</text>`).join('')}<text x="312" y="268" text-anchor="end" class="chart-muted">금리(%)</text></svg>`;
}
export function aiRateName(state){return {'ai-rate-intro':'finda_AIRate_Intro','ai-rate-consent':'finda_AIRate_ConsentSheet','ai-rate-loading':'finda_AIRate_Loading'}[state.screen]||(state.aiSort==='limit'?'finda_AIRate_Result_HighLimit':'finda_AIRate_Result_LowRate');}
function backButton(label){return `<header class="ai-rate-top"><button type="button" class="ai-rate-back" data-action="ai-rate-back" aria-label="${label}"><img src="assets/4b3e1.svg" alt="" width="24" height="24"></button></header>`;}
function introChart(){
 // Figma 3379:1545 sample chart; values are illustrative.
 return `<div class="ai-rate-intro-chart" role="img" aria-label="나와 비슷한 사람들이 받은 대출 분포 예시"><span class="chart-unit">한도 (만원)</span>${[[27,'4,000'],[88.2,'3,660'],[147.6,'3,330'],[207,'3,000']].map(([y,label])=>`<span class="chart-y" style="top:${y}px">${label}</span><i class="chart-grid" style="top:${y+9}px"></i>`).join('')}<i class="chart-axis"></i>${[[77.5,'3.6'],[154.17,'4.0'],[230.83,'4.4'],[307.5,'4.8']].map(([x,label])=>`<span class="chart-x" style="left:${x}px">${label}</span>`).join('')}<span class="chart-unit chart-x-unit">금리(%)</span><img class="chart-dots" src="assets/571ab.svg" alt="" width="340" height="270"><span class="chart-mine-label">내 조건</span><img class="chart-mine" src="assets/881ec.svg" alt="" width="36" height="36"></div>`;
}
function introBody(){return `${backButton('홈으로 돌아가기')}<div class="ai-rate-scroll"><section class="ai-rate-intro-hero"><h2>한도 조회 전 AI 예측값을<br>먼저 확인하세요</h2><img class="ai-rate-intro-orbit" src="assets/6a814.svg" alt="" width="116" height="116"><p class="ai-rate-intro-lead">대출, 이제 먼저 예측해보고 결정하세요.<br>신용조회 없이 핀다가 알려드릴게요.</p><ul class="ai-rate-intro-points"><li><span>매번 바뀌는 금리·한도, 일일이 조회하지<br>않아도 돼요.</span></li><li><span>나와 비슷한 사람들이 실제 받은 조건도 함께<br>비교해드려요.</span></li><li><span>핀다에 없는 금융기관까지 포함해서<br>알려드려요.</span></li></ul></section><section class="ai-rate-intro-update"><h3>예측 조건은 매일 업데이트돼요.<br>놓치지 않도록 2주마다 알려드릴게요.</h3><span class="ai-rate-intro-chip">예시 이미지</span><div class="ai-rate-intro-card"><div><p>내 예상 금리</p><strong>4.25%</strong></div><div><p>내 예상 한도</p><strong>3,500만원</strong></div></div>${introChart()}</section></div>`;}
export function aiRateIntro(){return `<div class="ai-rate-screen ai-rate-intro">${introBody()}<footer class="ai-rate-footer"><button type="button" class="primary" data-action="next">동의하기</button></footer></div>`;}
export function aiRateConsentSheet(checked){
 // Figma 3370:15299. 미체크 상태는 디자인에 없어 체크 아이콘을 회색으로 표시한다.
 const row=(id,icon,label,cls='')=>`<button type="button" class="ai-rate-check ${cls}" role="checkbox" aria-checked="${checked}" data-ai-consent="${id}">${icon}<span>${label}</span>${cls?'':'<img class="ai-rate-check-more" src="assets/7edab.svg" alt="" width="20" height="20">'}</button>`;
 return `<div class="ai-rate-screen ai-rate-intro" inert>${introBody()}<footer class="ai-rate-footer"><button type="button" class="primary" tabindex="-1">동의하기</button></footer></div><button type="button" class="ai-rate-dim" data-action="ai-rate-close" aria-label="서비스 동의 닫기" tabindex="-1"></button><section class="ai-rate-sheet" role="dialog" aria-modal="true" aria-labelledby="ai-rate-sheet-title"><span class="ai-rate-sheet-handle" aria-hidden="true"></span><h2 id="ai-rate-sheet-title">서비스 동의</h2>${row('all','<img src="assets/bc151.svg" alt="" width="24" height="24">','약관 전체 동의','all')}${row('prediction','<img src="assets/b4bcd.svg" alt="" width="20" height="20">','개인(신용)정보 수집·이용<br>동의[AI대출예측]')}<button type="button" class="primary" data-action="next" ${checked?'':'disabled'}>확인</button></section>`;
}
export function aiRateLoading(){return `<div class="ai-rate-screen ai-rate-loading">${backButton('홈으로 돌아가기')}<div class="ai-rate-loading-body" role="status"><h2>핀다 AI가 OOO님의 대출<br>조건을 예측하고 있어요...</h2><p>잠시만 기다려주세요.</p><img src="assets/fc7da.svg" alt="" width="136" height="136"></div></div>`;}
export function aiRateScreen(sort='rate'){return `<div class="ai-rate-screen"><header class="ai-rate-top"><button type="button" class="ai-rate-back" data-action="ai-rate-back" aria-label="홈으로 돌아가기">‹</button></header><div class="ai-rate-scroll"><section class="ai-rate-overview"><div class="ai-rate-notice"><span aria-hidden="true">i</span><p>매일 오전 7시에 최신 조건으로 바뀌어요.</p></div><div class="ai-rate-artwork">${predictionArtwork()}</div><h2>오늘 OOO님의<br>신용대출 AI 예상조건</h2><button type="button" class="ai-rate-explain" disabled>예측은 어떻게 이루어지나요? <span>›</span></button><div class="ai-rate-values"><div><p>내 예상 금리</p><strong>—<span>%</span></strong></div><div><p>내 예상 한도</p><strong>—<span>만원</span></strong></div></div><section class="ai-rate-policy"><h3><span aria-hidden="true">🎉</span> 정책상품 대상자예요!</h3><div class="ai-rate-values"><div><p>정책상품 금리</p><strong>—<span>%</span></strong></div><div><p>정책상품 한도</p><strong>—<span>만원</span></strong></div></div></section></section><section class="ai-rate-distribution"><h2>최근 한달간 나와 비슷한 사람들이 <span class="ai-rate-help" aria-hidden="true">?</span><br>실제로 받은 대출 분포예요</h2><p>내 예측 결과를 검증할 수 있는 데이터예요.</p>${scatterChart()}</section><section class="ai-rate-comparisons"><h2>나와 비슷한 사람들이 실제로 받은<br>금리·한도 조건이에요</h2><div class="ai-rate-tabs" role="tablist" aria-label="대출 조건 정렬"><button type="button" role="tab" aria-selected="${sort==='rate'}" data-ai-sort="rate">금리 낮은 순</button><button type="button" role="tab" aria-selected="${sort==='limit'}" data-ai-sort="limit">한도 높은 순</button></div><div class="ai-rate-offers">${[7,14,8].map((day,i)=>`<div class="ai-rate-offer"><div class="ai-rate-bank ${i===2?'blue':''}" aria-hidden="true">${i===2?'S':'a'}</div><div class="ai-rate-product"><strong>${i===2?'신한카드':'•••• 은행'}</strong><p>•••••• 대출</p><span class="ai-rate-badge">핀다입점상품</span></div><div class="ai-rate-terms"><strong>•••%</strong><b>•••만원</b><small>${day}일 전 실행된 대출</small></div><span class="ai-rate-chevron" aria-hidden="true">›</span></div>`).join('')}</div></section><section class="ai-rate-update"><button type="button" disabled>내 대출 정보 최신으로 업데이트 하기 <span>›</span></button></section></div><footer class="ai-rate-footer"><button type="button" class="primary" disabled>한도조회 해보기</button></footer></div>`;}
export function wireAiRate(root,onSort){
 for(const button of root.querySelectorAll('[data-ai-sort]'))button.addEventListener('click',()=>{
  for(const tab of root.querySelectorAll('[data-ai-sort]'))tab.setAttribute('aria-selected',String(tab===button));
  onSort?.(button.dataset.aiSort);
 });
}
